  it("initial bindings match the spec table (§9, §15, §22)", () => {
    const shortcutOf = (id: string) =>
      registry.get(id)?.shortcuts ?? [];
    expect(shortcutOf("file.openAudio")).toContain("Ctrl+O");
    expect(shortcutOf("transport.playPause")).toEqual(
      expect.arrayContaining(["Space", "K"]),
    );
    expect(shortcutOf("transport.stop")).toContain("Shift+Space");
    expect(shortcutOf("transport.jumpBack")).toContain("J");
    expect(shortcutOf("transport.jumpForward")).toContain("L");
    expect(shortcutOf("transport.toggleLoop")).toContain("Ctrl+L");
    expect(shortcutOf("view.concertPitch")).toContain("Ctrl+1");
    expect(shortcutOf("view.hornF")).toContain("Ctrl+2");
    expect(shortcutOf("edit.undo")).toContain("Ctrl+Z");
    expect(shortcutOf("edit.redo")).toContain("Ctrl+Shift+Z");
    // UI-050 review keys (P4-validated set).
    expect(shortcutOf("review.next")).toContain("ArrowRight");
    expect(shortcutOf("review.previous")).toContain("ArrowLeft");
    expect(shortcutOf("review.playSource")).toContain("R");
    expect(shortcutOf("review.accept")).toContain("O");
    expect(shortcutOf("review.dismiss")).toContain("Shift+O");
    expect(shortcutOf("review.pitchUp")).toContain("Alt+ArrowUp");
    expect(shortcutOf("review.pitchDown")).toContain("Alt+ArrowDown");
    expect(shortcutOf("review.deleteOrRestore")).toContain("Delete");
    expect(shortcutOf("export.open")).toContain("Ctrl+E");
    expect(shortcutOf("score.zoomIn")).toEqual(
      expect.arrayContaining(["Ctrl+=", "Ctrl++"]),
    );
    expect(shortcutOf("score.zoomOut")).toContain("Ctrl+-");
    expect(shortcutOf("score.zoomFit")).toContain("Ctrl+0");
    expect(shortcutOf("nav.nextRegion")).toContain("F6");
    expect(shortcutOf("nav.previousRegion")).toContain("Shift+F6");
  });
});

describe("conflict detection", () => {
  const cmd = (over: Partial<Command> & { id: string }): Command => ({
    title: "テスト",
    section: "app",
    run: () => undefined,
    ...over,
  });

  it("detects two commands bound to the same chord", () => {
    const registry = new CommandRegistry([
      cmd({ id: "a.one", shortcuts: ["Ctrl+P"] }),
      cmd({ id: "b.two", shortcuts: ["Ctrl+P"] }),
    ]);
    expect(registry.detectConflicts()).toEqual([
      { shortcut: "Ctrl+P", commandIds: ["a.one", "b.two"] },
    ]);
  });

  it("normalizes bindings before comparing (Ctrl+shift+p == Ctrl+Shift+P)", () => {
    const registry = new CommandRegistry([
      cmd({ id: "a.one", shortcuts: ["Ctrl+Shift+P"] }),
      cmd({ id: "b.two", shortcuts: ["ctrl+shift+p"] }),
    ]);
    expect(registry.detectConflicts()).toHaveLength(1);
  });

  it("detects multi-chord sequence collisions", () => {
    const registry = new CommandRegistry([
      cmd({ id: "a.one", shortcuts: ["Ctrl+K Ctrl+C"] }),
      cmd({ id: "b.two", shortcuts: ["Ctrl+K Ctrl+C"] }),
    ]);
    expect(registry.detectConflicts()).toHaveLength(1);
  });

  it("does not flag two bindings owned by the same command", () => {
    const registry = new CommandRegistry([
      cmd({ id: "a.one", shortcuts: ["Space", "K"] }),
      cmd({ id: "b.two", shortcuts: ["L"] }),
    ]);
    expect(registry.detectConflicts()).toEqual([]);
  });

  it("does not flag a chord vs. a longer sequence sharing its prefix", () => {
    // "Ctrl+K" alone and "Ctrl+K Ctrl+C" coexist: the single chord fires
    // immediately, so this is intentionally strict — they DO conflict at
    // the dispatcher level… except the first chord completes its binding
    // before the sequence can continue. Flagging it keeps authors honest:
    // sequences must not share their first chord with a single binding.
    const registry = new CommandRegistry([
      cmd({ id: "a.one", shortcuts: ["Ctrl+K"] }),
      cmd({ id: "b.two", shortcuts: ["Ctrl+K Ctrl+C"] }),
    ]);
    // Distinct normalized keys — no conflict between the *sequences*, the
    // dispatcher resolves "Ctrl+K" as a full match before any second chord.
    expect(registry.detectConflicts()).toEqual([]);
  });

  it("createCommandRegistry throws when definitions contain a conflict", () => {
    expect(() =>
      createCommandRegistry([
        cmd({ id: "a.one", shortcuts: ["Ctrl+X"] }),
        cmd({ id: "b.two", shortcuts: ["Ctrl+X"] }),
      ]),
    ).toThrow(/conflict/i);
  });

  it("register() rejects a duplicate command id", () => {
    const registry = new CommandRegistry([cmd({ id: "a.one" })]);
    expect(() => registry.register(cmd({ id: "a.one" }))).toThrow(
      /duplicate/i,
    );
  });
});

describe("invoke", () => {
  const registry = createCommandRegistry();

  it("runs an enabled command", () => {
    const ctx = mockContext();
    expect(registry.invoke("file.openAudio", ctx, SNAPSHOT_EMPTY)).toBe(true);
    expect(ctx.calls).toEqual(["openAudio"]);
  });

  it("refuses a disabled command — non-executable from any surface", () => {
    const ctx = mockContext();
    // 採譜 needs audio; EMPTY state has none.
    expect(registry.invoke("score.transcribe", ctx, SNAPSHOT_EMPTY)).toBe(
      false,
    );
    expect(ctx.transcribe).not.toHaveBeenCalled();
  });

  it("returns false for unknown ids", () => {
    const ctx = mockContext();
    expect(registry.invoke("no.such", ctx, SNAPSHOT_EMPTY)).toBe(false);
  });

  it("enables transport/edit/export once a score exists", () => {
    const ctx = mockContext();
    for (const [id, spy] of [
      ["transport.toggleLoop", "toggleLoop"],
      ["edit.undo", "undo"],
      ["export.open", "openExport"],
      ["review.next", null], // needs reviewOpen — stays disabled
    ] as const) {
      const ran = registry.invoke(id, ctx, SNAPSHOT_SCORE);
      if (spy) {
        expect(ran).toBe(true);
        expect(ctx.calls).toContain(spy);
      } else {
        expect(ran).toBe(false);
      }
    }
  });
});

describe("visibility", () => {
  const registry = createCommandRegistry();

  it("review commands stay off surfaces until a review exists", () => {
    const visibleEmpty = registry
      .listVisible(SNAPSHOT_EMPTY)
      .map((c) => c.id);
    expect(visibleEmpty).not.toContain("review.open");
    expect(visibleEmpty).not.toContain("review.next");

    const reviewing: CommandSnapshot = {
      ...SNAPSHOT_SCORE,
      reviewOpen: true,
    };
    const visibleReview = registry
      .listVisible(reviewing)
      .map((c) => c.id);
    expect(visibleReview).toContain("review.open");
    expect(visibleReview).toContain("review.next");
    expect(visibleReview).toContain("review.previous");
  });
});

/**
 * Command model types (docs/GUI_UX_SPEC.md §23).
 *
 * A Command is a *stateless* description: predicates receive a
 * CommandSnapshot so the same definitions can be evaluated for menus,
 * keyboard dispatch, palette listing and tests without re-registering.
 */

/** Pitch display modes (GUI_UX_SPEC §7). Kept literal here so the command
 *  layer does not depend on a component file. */
export type PitchViewSetting = "concert" | "hornF";

/** Top-level screens that gate command availability. */
export type AppView = "workspace" | "settings";

/** Grouping for menus / command palette / docs. */
export type CommandSection =
  | "file"
  | "score"
  | "transport"
  | "view"
  | "review"
  | "edit"
  | "export"
  | "nav"
  | "app";

/**
 * Immutable read of the app state that command predicates evaluate.
 * The app builds one per render; the registry never stores it.
 */
export interface CommandSnapshot {
  /** A source audio file is loaded (GUI_UX_SPEC §4, AUDIO_READY+). */
  readonly hasAudio: boolean;
  /** A canonical score exists (SCORE_READY+). */
  readonly hasScore: boolean;
  /** Transcription is running — score-writing commands disable (§5). */
  readonly isTranscribing: boolean;
  /** Audio is currently playing (drives the play/pause affordance). */
  readonly isPlaying: boolean;
  /** Loop range playback is armed. */
  readonly loopEnabled: boolean;
  /** Current pitch display mode. */
  readonly pitch: PitchViewSetting;
  /** Undo/redo stacks (§14 — all edits are commands). */
  readonly canUndo: boolean;
  readonly canRedo: boolean;
  /** A note/region is selected (gates Esc = clear selection). */
  readonly hasSelection: boolean;
  /** #113: a waveform range selection exists (AUDIO_READY). Esc clears
   *  this before any score selection (spec 8: Esc -> 選択解除). */
  readonly hasWaveformSelection: boolean;
  /** 要確認 workspace state. */
  readonly reviewOpen: boolean;
  readonly reviewCount: number;
  /** FEAT-001: a recording session is in progress (loopback/mic). */
  readonly isRecording: boolean;
  /** FEAT-001 (#80): the recording session is paused. */
  readonly isRecordingPaused: boolean;
  /** FEAT-001: score audition (auto-playback of the score) is on. */
  readonly auditionEnabled: boolean;
  /** Active top-level view. */
  readonly view: AppView;
}

/**
 * The services commands act on. The app supplies implementations; during
 * the spike most are stubs that announce via `announce` so every invocation
 * produces honest feedback in the (aria-live) status bar.
 */
export interface CommandContext {
  openAudio(): void;
  transcribe(): void;
  /**
   * Cooperative `job.cancel` (UI-040): requests cancellation of the
   * in-flight transcription; the job still ends in a terminal `cancelled`
   * event, so callers must not assume an instant stop. Optional so older
   * test contexts keep compiling — an absent implementation is a no-op.
   */
  cancelTranscription?(): void;
  togglePlayPause(): void;
  stop(): void;
  jumpBack(): void;
  jumpForward(): void;
  seekToStart(): void;
  seekToEnd(): void;
  toggleLoop(): void;
  /**
   * FEAT-001 (#60): PC再生音源/マイク録音と楽譜自動演奏。
   * Optional so older test contexts keep compiling.
   */
  captureSystemAudio?(): void;
  captureMicrophone?(): void;
  /** 録音中なら停止して取り込む / 録音していなければ何もしない。 */
  stopCapture?(): void;
  /** 録音を中止して破棄する。 */
  cancelCapture?(): void;
  /** 録音を一時停止する(#80)。 */
  pauseCapture?(): void;
  /** 一時停止した録音を再開する(#80)。 */
  resumeCapture?(): void;
  /** 楽譜の自動演奏トグル(スコアクロックに同期して発音)。 */
  toggleScoreAudition?(): void;
  /** 元音源のミュート切替(#72)。楽譜の演奏だけを聴く用途。 */
  toggleSourceMute?(): void;
  setPitchView(view: PitchViewSetting): void;
  openReview(): void;
  reviewNext(): void;
  reviewPrevious(): void;
  /**
   * UI-050 review-workspace actions (GUI_UX_SPEC §12). Optional like
   * `cancelTranscription` so leaner test contexts keep compiling — an
   * absent implementation is a no-op.
   */
  reviewAccept?(): void;
  reviewDismiss?(): void;
  reviewPlaySource?(): void;
  reviewPitchUp?(): void;
  reviewPitchDown?(): void;
  reviewDeleteOrRestore?(): void;
  exitReview?(): void;
  undo(): void;
  redo(): void;
  openExport(): void;
  /** #100: プロジェクトを保存 — opens the save-file picker and writes
   *  .hornscribe.json through the engine. Optional like the other
   *  late-binding commands; absent = no-op. */
  saveProject?(): void;
  zoomScoreIn(): void;
  zoomScoreOut(): void;
  zoomScoreFit(): void;
  clearSelection(): void;
  /** #113: Esc on a waveform selection (AUDIO_READY) - clears the range
   *  back to "all" (spec 8: Esc -> 選択解除). Optional: absent = no-op. */
  clearWaveformSelection?(): void;
  openSettings(): void;
  /** Opens the 診断情報 sheet (§19 — separated from the normal UI). */
  openDiagnostics(): void;
  /** F6 region navigation — implemented by focus/zones. */
  focusNextRegion(): void;
  focusPreviousRegion(): void;
  /**
   * Surface command feedback in the status area (role="status" is
   * aria-live, so Narrator users hear the result — UX_VALIDATION §11).
   */
  announce(message: string): void;
}

/**
 * A single invocable command — the unit the registry, command bar, menus,
 * palette and keyboard dispatcher all share (single source of truth).
 */
export interface Command {
  /** Stable dotted id, e.g. "transport.playPause". */
  readonly id: string;
  /**
   * Japanese title — the only UI language (UI_COPY_CONTRACT). This is what
   * buttons, menus, a palette and screen readers all announce.
   */
  readonly title: string;
  /** Optional longer Japanese description for palettes/menus. */
  readonly description?: string;
  readonly section: CommandSection;
  /**
   * Keyboard bindings in "Ctrl+Shift+Z" notation; whitespace separates
   * chords in a multi-step sequence. The first entry is the canonical
   * binding shown in tooltips / aria-keyshortcuts.
   */
  readonly shortcuts?: readonly string[];
  /**
   * May run against this snapshot. Default: enabled. Disabled commands are
   * non-executable everywhere — toolbar, menu AND shortcut (issue req:
   * "disabled commands remain non-executable via shortcut").
   */
  readonly isEnabled?: (snapshot: CommandSnapshot) => boolean;
  /**
   * Listed on command surfaces (palette/menus/overflow). Default: visible.
   * Hidden commands still run when enabled — e.g. 採譜し直す vs 採譜.
   */
  readonly isVisible?: (snapshot: CommandSnapshot) => boolean;
  /** May fire while a text field / IME host has focus. Default false. */
  readonly allowInTextInput?: boolean;
  /** May fire while a modal dialog/sheet owns focus. Default false. */
  readonly allowInModal?: boolean;
  /** Re-fires on key auto-repeat. Default false (no accidental toggles). */
  readonly allowRepeat?: boolean;
  /** Execute against live services. */
  readonly run: (ctx: CommandContext, snapshot: CommandSnapshot) => void;
}

