function withShortcut(title: string, shortcut?: string): string {
  return shortcut ? `${title}（${shortcut}）` : title;
}

/**
 * Transport bar (GUI_UX_SPEC §9). Mounted only once audio exists; every
 * control stays disabled while a command's snapshot predicate is false.
 *
 * All actions dispatch through the command surface (§23) — the Space key,
 * this button and a future menu item are the same command, so enabled
 * state and Japanese labels can never disagree across surfaces.
 *
 * `live` mirrors the transport adapter's low-frequency snapshot (UI-020):
 * play/pause icon, the MM:SS.t position/duration readout and the rate
 * button reflect the real audio clock. When no media transport is live but
 * a score clock runs (dev score-only path, UI-030), `timeLabel` supplies
 * the same readout; otherwise the static placeholder shows.
 */
export function TransportBar({
  commands,
  live,
  onCycleRate,
  timeLabel,
  followEnabled,
  followSuspended,
  onToggleFollow,
  auditionEnabled,
  loopArmed,
}: {
  commands: CommandSurface;
  live?: {
    isPlaying: boolean;
    positionSec: number;
    durationSec: number;
    rate: number;
    /** 元音源ミュート状態(#72)。 */
    muted?: boolean;
  };
  /** 再生速度 button — cycles SUPPORTED_RATES when the transport is live. */
  onCycleRate?(): void;
  /** [UI-030] "mm:ss.t / mm:ss.t" readout from the score clock when the
   *  media transport has no loaded source (score-only playback). */
  timeLabel?: string;
  /** [UI-030] 再生位置追従 armed state (§11); undefined = no score clock. */
  followEnabled?: boolean;
  /** [UI-030] Manual scroll suspended follow — button resumes it. */
  followSuspended?: boolean;
  onToggleFollow?(): void;
  /** FEAT-001 (#60): 楽譜の自動演奏がオンか(score clock がある時のみ)。 */
  auditionEnabled?: boolean;
  /** #113: A-B loop armed (media loop or score loop) - pressed state. */
  loopArmed?: boolean;
}) {
  // All transport commands share the hasAudio gate (see definitions).
  const enabled = commands.isEnabled("transport.playPause");
  const position = live
    ? formatTimecode(live.positionSec)
    : (timeLabel?.split(" / ")[0] ?? ja.time.zero);
  const duration = live
    ? formatTimecode(live.durationSec)
    : (timeLabel?.split(" / ")[1] ?? ja.time.zeroTotal);
  const rateLabel = live ? `${live.rate}×` : "1.0×";
  return (
    <Toolbar
      className="hs-transport"
      aria-label={ja.transport.regionLabel}
      data-hs-focus-zone="transport"
      tabIndex={-1}
    >
      <Tooltip
        content={withShortcut(
          commands.title("transport.seekStart"),
          commands.shortcutLabel("transport.seekStart"),
        )}
        relationship="label"
      >
        <ToolbarButton
          icon={<Previous24Regular />}
          aria-label={commands.title("transport.seekStart")}
          aria-keyshortcuts="Home"
          disabled={!commands.isEnabled("transport.seekStart")}
          onClick={() => commands.invoke("transport.seekStart")}
        />
      </Tooltip>
      <Tooltip
        content={withShortcut(
          commands.title("transport.jumpBack"),
          commands.shortcutLabel("transport.jumpBack"),
        )}
        relationship="label"
      >
        <ToolbarButton
          icon={<Rewind24Regular />}
          aria-label={commands.title("transport.jumpBack")}
          aria-keyshortcuts="J"
          disabled={!commands.isEnabled("transport.jumpBack")}
          onClick={() => commands.invoke("transport.jumpBack")}
        />
      </Tooltip>
      <Tooltip
        content={withShortcut(
          commands.title("transport.playPause"),
          commands.shortcutLabel("transport.playPause"),
        )}
        relationship="label"
      >
        <ToolbarButton
          icon={live?.isPlaying ? <Pause24Regular /> : <Play24Regular />}
          aria-label={
            live?.isPlaying ? ja.transport.pause : ja.transport.play
          }
          aria-keyshortcuts="Space K"
          disabled={!commands.isEnabled("transport.playPause")}
          appearance="primary"
          onClick={() => commands.invoke("transport.playPause")}
        />
      </Tooltip>
      <Tooltip
        content={withShortcut(
          commands.title("transport.stop"),
          commands.shortcutLabel("transport.stop"),
        )}
        relationship="label"
      >
        <ToolbarButton
          icon={<Stop24Regular />}
          aria-label={commands.title("transport.stop")}
          aria-keyshortcuts="Shift+Space"
          disabled={!commands.isEnabled("transport.stop")}
          onClick={() => commands.invoke("transport.stop")}
        />
      </Tooltip>
      <Tooltip
        content={withShortcut(
          commands.title("transport.jumpForward"),
          commands.shortcutLabel("transport.jumpForward"),
        )}
        relationship="label"
      >
        <ToolbarButton
          icon={<FastForward24Regular />}
          aria-label={commands.title("transport.jumpForward")}
          aria-keyshortcuts="L"
          disabled={!commands.isEnabled("transport.jumpForward")}
          onClick={() => commands.invoke("transport.jumpForward")}
        />
      </Tooltip>
      <Tooltip
        content={withShortcut(
          commands.title("transport.seekEnd"),
          commands.shortcutLabel("transport.seekEnd"),
        )}
        relationship="label"
      >
        <ToolbarButton
          icon={<Next24Regular />}
          aria-label={commands.title("transport.seekEnd")}
          aria-keyshortcuts="End"
          disabled={!commands.isEnabled("transport.seekEnd")}
          onClick={() => commands.invoke("transport.seekEnd")}
        />
      </Tooltip>
      <span className="hs-transport__time" aria-label={ja.transport.position}>
        {position} / {duration}
      </span>

      <span className="hs-transport__spacer" />

      <Tooltip
        content={`${ja.transport.rate} ${rateLabel}`}
        relationship="label"
      >
        <ToolbarButton
          aria-label={`${ja.transport.rate} ${rateLabel}`}
          disabled={!enabled}
          onClick={onCycleRate}
        >
          {rateLabel}
        </ToolbarButton>
      </Tooltip>
      <Tooltip
        content={withShortcut(
          commands.title("transport.toggleLoop"),
          commands.shortcutLabel("transport.toggleLoop"),
        )}
        relationship="label"
      >
        <ToolbarButton
          icon={<ArrowRepeatAll24Regular />}
          aria-label={commands.title("transport.toggleLoop")}
          aria-keyshortcuts="Control+L"
          aria-pressed={loopArmed === true}
          disabled={!commands.isEnabled("transport.toggleLoop")}
          onClick={() => commands.invoke("transport.toggleLoop")}
        />
      </Tooltip>
      <Tooltip
        content={
          followSuspended ? ja.scoreView.resumeFollow : ja.transport.follow
        }
        relationship="label"
      >
        <ToolbarButton
          icon={<SlideTextSparkle24Regular />}
          aria-label={
            followSuspended ? ja.scoreView.resumeFollow : ja.transport.follow
          }
          aria-pressed={followEnabled === true && !followSuspended}
          disabled={!enabled}
          onClick={onToggleFollow}
        />
      </Tooltip>
      {/* FEAT-001: 楽譜の自動演奏。スコアがある時だけ有効。 */}
      <Tooltip
        content={
          auditionEnabled ? ja.transport.auditionOn : ja.transport.auditionOff
        }
        relationship="label"
      >
        <ToolbarButton
          icon={<MusicNote2PlayRegular />}
          aria-label={
            auditionEnabled
              ? ja.transport.auditionOn
              : ja.transport.auditionOff
          }
          aria-pressed={auditionEnabled === true}
          disabled={!commands.isEnabled("transport.toggleAudition")}
          onClick={() => commands.invoke("transport.toggleAudition")}
        />
      </Tooltip>
      {/* #72: 元音源のミュート — 楽譜の演奏だけを聴く用途。 */}
      <Tooltip
        content={
          live?.muted ? ja.transport.unmuteSource : ja.transport.muteSource
        }
        relationship="label"
      >
        <ToolbarButton
          icon={live?.muted ? <SpeakerMute24Regular /> : <Speaker224Regular />}
          aria-label={
            live?.muted ? ja.transport.unmuteSource : ja.transport.muteSource
          }
          aria-pressed={live?.muted === true}
          disabled={!commands.isEnabled("transport.toggleSourceMute")}
          onClick={() => commands.invoke("transport.toggleSourceMute")}
        />
      </Tooltip>
    </Toolbar>
  );
}

import { useEffect, useMemo, useRef, useState } from "react";
import { Tooltip } from "@fluentui/react-components";
import {
  ArrowRepeatAll24Regular,
  Play24Regular,
  ZoomIn24Regular,
  Dismiss24Regular,
  ZoomFit24Regular,
} from "@fluentui/react-icons";
import { ja } from "../strings/ja";
import { resizeKeyDelta, startPointerResize } from "../workspace/layout";
import type { LoadedAudio } from "../import/types";
import type { CaptureState } from "../capture/controller";
import { formatTimecode } from "../import/format";
import {
  clientXInView,
  clampView,
  DRAG_THRESHOLD_PX,
  fullView,
  isFullView,
  normalizeSelection,
  panView,
  selectionBandInView,
  zoomView,
  type SelectionRange,
  type ViewRange,
} from "../import/selection";

/** Peak-column path for the strip: one <path> keeps redraw cost flat -
 *  vertical bars centred on the midline. `peaks` is the slice currently
 *  inside the zoom window.
 */
function peaksPath(peaks: readonly number[]): string {
  let d = "";
  for (let i = 0; i < peaks.length; i++) {
    const p = Math.min(1, Math.max(0, peaks[i]));
    d += `M${i + 0.5} ${50 - p * 48}L${i + 0.5} ${50 + p * 48}`;
  }
  return d;
}

/** Slice the peaks array to the visible window so zooming redraws the
 *  same columns at a wider pitch (spec 8: Ctrl+wheel zoom). */
function peaksInView(
  peaks: readonly number[],
  view: ViewRange,
  durationSec: number,
): readonly number[] {
  if (durationSec <= 0 || peaks.length === 0) return peaks;
  const lo = Math.max(0, Math.floor((view.startSec / durationSec) * peaks.length));
  const hi = Math.min(
    peaks.length,
    Math.max(lo + 1, Math.ceil((view.endSec / durationSec) * peaks.length)),
  );
  return peaks.slice(lo, hi);
}

/**
 * Waveform / timeline region (GUI_UX_SPEC 2, 8).
 * Height is user-resizable: 64px minimum up to ~35% of the work area, and
 * always smaller than the score. The bottom-edge separator supports pointer
 * drag, ArrowUp/ArrowDown (±8px) and double-click reset - deterministic
 * clamps live in workspace/layout.ts.
 *
 * UI-020: renders decoded peaks + playhead once audio loads (spec 4), the
 * loading line while OPENING_AUDIO, and click-to-seek
 * (spec 8) against the transport clock.
 *
 * #88: when `onSelect` is provided (AUDIO_READY), a horizontal drag past
 * DRAG_THRESHOLD_PX commits a selection range instead of seeking - the
 * committed band plus live drag preview paint over the peaks. A plain
 * click still seeks so the user can audition the range edges.
 *
 * #113 (spec 8): the committed selection carries edge handles and a
 * context action bar (loop / play / zoom / clear); Esc clears it.
 * Ctrl+wheel zooms the visible window around the cursor and a plain wheel
 * pans it once zoomed; the zoom chip resets to the whole clip. The armed
 * A-B loop paints as a second band (`loop` prop).
*/
export function WaveformView({
  height,
  min,
  max,
  onResize,
  onReset,
  audio,
  loading = false,
  positionSec,
  onSeek,
  captureState,
  selection,
  onSelect,
  loop,
  onLoopSelection,
  onPlaySelection,
  onClearSelection,
}: {
  height: number;
  min: number;
  max: number;
  onResize(px: number): void;
  onReset(): void;
  /** Decoded audio (UI-020) - peaks render, null keeps the placeholder. */
  audio?: Pick<
    LoadedAudio,
    "fileName" | "durationSeconds" | "peaks"
  > | null;
  /** OPENING_AUDIO - honest loading line instead of fake peaks. */
  loading?: boolean;
  /** Audio-clock position for the playhead (seconds). */
  positionSec?: number;
  /** spec 8 click -> seek: receives the target time in seconds. */
  onSeek?(seconds: number): void;
  /** FEAT-001 (#60): recording state - while a capture runs the strip
   *  shows the live recording status instead of a file's peaks. */
  captureState?: CaptureState | null;
  /** #88: committed selection (seconds) - renders the band when set. */
  selection?: SelectionRange | null;
  /** #88: drag-to-select - when absent the strip stays seek-only. */
  onSelect?(range: SelectionRange): void;
  /** #113: armed media A-B loop (seconds) - painted as a second band. */
  loop?: SelectionRange | null;
  /** #113: context action - arm/clear the A-B loop on this range. */
  onLoopSelection?(range: SelectionRange): void;
  /** #113: context action - play [start, end) once, then pause. */
  onPlaySelection?(range: SelectionRange): void;
  /** #113: context action / Esc - drop the committed selection. */
  onClearSelection?(): void;
}) {
  const duration = audio?.durationSeconds ?? 0;

  // spec 15: the zoom window lives inside the strip - it resets whenever a
  // different clip loads (identity change), never mid-gesture.
  const [view, setView] = useState<ViewRange>(() => fullView(duration));
  const audioRef = useRef(audio);
  if (audioRef.current !== audio) {
    audioRef.current = audio;
    setView(fullView(duration));
  }

  const rootRef = useRef<HTMLDivElement | null>(null);
  const viewRef = useRef(view);
  viewRef.current = view;
  const durationRef = useRef(duration);
  durationRef.current = duration;

  // Ctrl+wheel zoom / wheel pan need preventDefault, so the listener is
  // attached non-passively (React registers wheel handlers as passive).
  useEffect(() => {
    const el = rootRef.current;
    if (!el) return;
    const onWheel = (e: WheelEvent) => {
      const dur = durationRef.current;
      if (dur <= 0) return;
      const rect = el.getBoundingClientRect();
      if (e.ctrlKey || e.metaKey) {
        e.preventDefault();
        const anchor = clientXInView(e.clientX, rect.left, rect.width, viewRef.current);
        const factor = e.deltaY < 0 ? 0.8 : 1.25;
        setView(zoomView(viewRef.current, anchor, factor, dur));
        return;
      }
      if (isFullView(viewRef.current, dur)) return;
      e.preventDefault();
      const span = viewRef.current.endSec - viewRef.current.startSec;
      const deltaPx = Math.abs(e.deltaX) > Math.abs(e.deltaY) ? e.deltaX : e.deltaY;
      setView(panView(viewRef.current, (deltaPx / Math.max(1, rect.width)) * span, dur));
    };
    el.addEventListener("wheel", onWheel, { passive: false });
    return () => el.removeEventListener("wheel", onWheel);
  }, []);

  const visiblePeaks = useMemo(
    () => (audio ? peaksInView(audio.peaks, view, duration) : []),
    [audio, view, duration],
  );
  const path = useMemo(() => peaksPath(visiblePeaks), [visiblePeaks]);

  const span = view.endSec - view.startSec;
  const ratio =
    positionSec != null && span > 0 &&
    positionSec >= view.startSec && positionSec <= view.endSec
      ? Math.min(1, Math.max(0, (positionSec - view.startSec) / span))
      : null;

  // #88: drag gesture - a press+release under DRAG_THRESHOLD_PX stays a
  // click (seek); past it the gesture becomes a range selection.
  const [dragRange, setDragRange] = useState<SelectionRange | null>(null);
  const gesture = useRef<{
    pointerId: number;
    startX: number;
    startSec: number;
    rect: DOMRect;
    dragging: boolean;
  } | null>(null);

  const onPointerDown = (e: React.PointerEvent<HTMLDivElement>) => {
    if (!audio || duration <= 0 || e.button !== 0) return;
    const rect = e.currentTarget.getBoundingClientRect();
    const g = {
      pointerId: e.pointerId,
      startX: e.clientX,
      startSec: clientXInView(e.clientX, rect.left, rect.width, viewRef.current),
      rect,
      dragging: false,
    };
    gesture.current = g;
    const move = (ev: PointerEvent) => {
      if (gesture.current !== g || ev.pointerId !== g.pointerId) return;
      if (!g.dragging) {
        if (Math.abs(ev.clientX - g.startX) < DRAG_THRESHOLD_PX) return;
        if (!onSelect) return; // seek-only strip: drags do nothing
        g.dragging = true;
      }
      const sec = clientXInView(
        ev.clientX,
        g.rect.left,
        g.rect.width,
        viewRef.current,
      );
      setDragRange(normalizeSelection(g.startSec, sec, duration));
    };
    const finish = (commit: boolean) => (ev: PointerEvent) => {
      if (gesture.current !== g || ev.pointerId !== g.pointerId) return;
      window.removeEventListener("pointermove", move);
      window.removeEventListener("pointerup", onUp);
      window.removeEventListener("pointercancel", onCancel);
      gesture.current = null;
      if (g.dragging) {
        setDragRange(null);
        if (commit && onSelect) {
          const sec = clientXInView(
            ev.clientX,
            g.rect.left,
            g.rect.width,
            viewRef.current,
          );
          onSelect(normalizeSelection(g.startSec, sec, duration));
        }
      } else if (commit && onSeek) {
        onSeek(g.startSec);
      }
    };
    const onUp = finish(true);
    const onCancel = finish(false);
    window.addEventListener("pointermove", move);
    window.addEventListener("pointerup", onUp);
    window.addEventListener("pointercancel", onCancel);
  };

  // #113: edge handles on the committed band - dragging one edge keeps the
  // other anchored and re-commits through onSelect.
  const onHandleDown = (edge: "start" | "end") =>
    (e: React.PointerEvent<HTMLDivElement>) => {
      if (!selection || !onSelect || e.button !== 0) return;
      e.stopPropagation();
      const rect = rootRef.current?.getBoundingClientRect();
      if (!rect) return;
      const pointerId = e.pointerId;
      const move = (ev: PointerEvent) => {
        if (ev.pointerId !== pointerId) return;
        const sec = clientXInView(ev.clientX, rect.left, rect.width, viewRef.current);
        const next =
          edge === "start"
            ? normalizeSelection(sec, selection.endSec, duration)
            : normalizeSelection(selection.startSec, sec, duration);
        onSelect(next);
      };
      const up = (ev: PointerEvent) => {
        if (ev.pointerId !== pointerId) return;
        window.removeEventListener("pointermove", move);
        window.removeEventListener("pointerup", up);
        window.removeEventListener("pointercancel", up);
      };
      window.addEventListener("pointermove", move);
      window.addEventListener("pointerup", up);
      window.addEventListener("pointercancel", up);
    };

  const liveBand = selectionBandInView(dragRange, view);
  const committedBand = selectionBandInView(selection ?? null, view);
  const band = liveBand ?? committedBand;
  const bandRange = dragRange ?? selection ?? null;
  const loopBand = selectionBandInView(loop ?? null, view);
  const zoomed = !isFullView(view, duration);

  const clearCommitted = () => {
    onClearSelection?.();
  };

  return (
    <div
      ref={rootRef}
      className={onSelect ? "hs-waveform hs-waveform--selectable" : "hs-waveform"}
      role="region"
      aria-label={ja.waveform.regionLabel}
      data-hs-focus-zone="waveform"
      tabIndex={0}
      style={{ height }}
      onPointerDown={onPointerDown}
      onKeyDown={(e) => {
        // spec 8: Esc clears the committed selection first, then zoom.
        if (e.key !== "Escape") return;
        if (selection) {
          e.stopPropagation();
          clearCommitted();
        } else if (zoomed) {
          e.stopPropagation();
          setView(fullView(duration));
        }
      }}
    >
      {loading ? (
        <span className="hs-waveform__placeholder">
          {ja.import.waveform.loading}
        </span>
      ) : captureState?.phase === "recording" ? (
        <span
          className="hs-waveform__recording"
          role="status"
          aria-live="polite"
        >
          {captureState.source === "loopback"
            ? ja.transport.recordingLoopbackLabel
            : ja.transport.recordingLabel}
          {" - "}
          {formatTimecode(captureState.elapsedSeconds)}
          {captureState.deviceName ? ` · ${captureState.deviceName}` : ""}
          {/* #71: 入力レベルの簡易メーター(0-1 のピーク)。 */}
          <span
            className="hs-waveform__level"
            aria-hidden="true"
          >
            <span
              className="hs-waveform__level-fill"
              style={{
                width: `${Math.round(
                  Math.min(1, Math.max(0, captureState.level ?? 0)) * 100,
                )}%`,
              }}
            />
          </span>
        </span>
      ) : audio ? (
        <>
          <svg
            className="hs-waveform__peaks"
            viewBox={`0 0 ${Math.max(1, visiblePeaks.length)} 100`}
            preserveAspectRatio="none"
            aria-hidden="true"
          >
            <path d={path} />
          </svg>
          {loopBand ? (
            <div
              className="hs-waveform__loop"
              style={{
                left: loopBand.left * 100 + "%",
                width: loopBand.width * 100 + "%",
              }}
              aria-hidden="true"
            />
          ) : null}
          {band ? (
            <div
              className={liveBand
                ? "hs-waveform__selection hs-waveform__selection--live"
                : "hs-waveform__selection"}
              style={{
                left: band.left * 100 + "%",
                width: band.width * 100 + "%",
              }}
              aria-hidden="true"
            >
              {bandRange ? (
                <span className="hs-waveform__selection-label">
                  {formatTimecode(bandRange.startSec)}
                  {" - "}
                  {formatTimecode(bandRange.endSec)}
                </span>
              ) : null}
            </div>
          ) : null}
          {/* #113: edge handles on the committed band only - the live
              preview is already following the pointer. */}
          {committedBand && !liveBand && onSelect ? (
            <>
              <div
                className="hs-waveform__handle hs-waveform__handle--start"
                style={{ left: `calc(${committedBand.left * 100}% - 4px)` }}
                onPointerDown={onHandleDown("start")}
              />
              <div
                className="hs-waveform__handle hs-waveform__handle--end"
                style={{
                  left: `calc(${(committedBand.left + committedBand.width) * 100}% - 4px)`,
                }}
                onPointerDown={onHandleDown("end")}
              />
            </>
          ) : null}
          {ratio !== null ? (
            <div
              className="hs-waveform__playhead"
              style={{ left: `${ratio * 100}%` }}
              aria-hidden="true"
            />
          ) : null}
          <span className="hs-waveform__name" aria-hidden="true">
            {audio.fileName}
          </span>
          {/* #113: context actions for the committed selection (spec 8). */}
          {committedBand && !liveBand ? (
            <div
              className="hs-waveform__actions"
              role="toolbar"
              aria-label={ja.waveform.selectionActions}
              style={{
                left: `${Math.min(
                  96,
                  (committedBand.left + committedBand.width) * 100,
                )}%`,
              }}
              onPointerDown={(e) => e.stopPropagation()}
            >
              <Tooltip content={ja.waveform.loopSelection} relationship="label">
                <button
                  type="button"
                  className="hs-waveform__action"
                  aria-label={ja.waveform.loopSelection}
                  onClick={() =>
                    selection && onLoopSelection?.(selection)
                  }
                >
                  <ArrowRepeatAll24Regular />
                </button>
              </Tooltip>
              <Tooltip content={ja.waveform.playSelection} relationship="label">
                <button
                  type="button"
                  className="hs-waveform__action"
                  aria-label={ja.waveform.playSelection}
                  onClick={() =>
                    selection && onPlaySelection?.(selection)
                  }
                >
                  <Play24Regular />
                </button>
              </Tooltip>
              <Tooltip content={ja.waveform.zoomSelection} relationship="label">
                <button
                  type="button"
                  className="hs-waveform__action"
                  aria-label={ja.waveform.zoomSelection}
                  onClick={() =>
                    selection &&
                    setView(clampView(selection, duration))
                  }
                >
                  <ZoomIn24Regular />
                </button>
              </Tooltip>
              <Tooltip content={ja.waveform.clearSelection} relationship="label">
                <button
                  type="button"
                  className="hs-waveform__action"
                  aria-label={ja.waveform.clearSelection}
                  onClick={clearCommitted}
                >
                  <Dismiss24Regular />
                </button>
              </Tooltip>
            </div>
          ) : null}
          {/* #113: zoomed-state chip - one click back to the whole clip. */}
          {zoomed ? (
            <Tooltip content={ja.waveform.resetZoom} relationship="label">
              <button
                type="button"
                className="hs-waveform__zoom-reset"
                aria-label={ja.waveform.resetZoom}
                onClick={() => setView(fullView(duration))}
                onPointerDown={(e) => e.stopPropagation()}
              >
                <ZoomFit24Regular />
                <span>{ja.waveform.zoomedLabel}</span>
              </button>
            </Tooltip>
          ) : null}
        </>
      ) : (
        <span className="hs-waveform__placeholder">
          {ja.waveform.placeholder}
        </span>
      )}
      <div
        className="hs-waveform__resizer"
        role="separator"
        aria-orientation="horizontal"
        aria-label={ja.waveform.resizeHandle}
        aria-valuemin={min}
        aria-valuemax={max}
        aria-valuenow={height}
        tabIndex={0}
        onPointerDown={(e) => {
          // Keep the resize gesture out of the strip's select/seek
          // pointerdown (it bubbles up to .hs-waveform otherwise).
          e.stopPropagation();
          const startH = height;
          const startY = e.clientY;
          startPointerResize(e, onResize, (_x, y) => startH + (y - startY));
        }}
        onClick={(e) => e.stopPropagation()}
        onKeyDown={(e) => {
          const next = resizeKeyDelta(e, height);
          if (next != null) {
            e.preventDefault();
            onResize(next);
          }
        }}
        onDoubleClick={onReset}
      />
    </div>
  );
}

/**
 * MediaElementTransport tests (UI-020 adapter over the UI-004 contract).
 * A FakePort stands in for HTMLAudioElement — the adapter's state machine,
 * snapshot emission and loop/seek/rate rules are what get asserted.
 */

import { describe, expect, it, vi } from "vitest";
import {
  MediaElementTransport,
  MIN_LOOP_SECONDS,
  type MediaPort,
  type MediaPortHandlers,
  type TransportSnapshot,
} from "./mediaTransport";
import type { MediaSource } from "./types";

class FakePort implements MediaPort {
  time = 0;
  duration = 120;
  rate = 1;
  preservePitch = true;
  playing = false;
  loaded: MediaSource | null = null;
  seekCalls: number[] = [];
  failLoad = false;
  private handlers = new Set<MediaPortHandlers>();

  async load(source: MediaSource): Promise<void> {
    if (this.failLoad) throw new Error("load failed");
    this.loaded = source;
  }
  async play(): Promise<void> {
    this.playing = true;
  }
  pause(): void {
    this.playing = false;
  }
  seekTo(seconds: number): void {
    this.time = seconds;
    this.seekCalls.push(seconds);
  }
  setRate(rate: number): void {
    this.rate = rate;
  }
  setPreservePitch(on: boolean): void {
    this.preservePitch = on;
  }
  muted = false;
  setMuted(on: boolean): void {
    this.muted = on;
  }
  getTime(): number {
    return this.time;
  }
  getDuration(): number {
    return this.duration;
  }
  subscribe(handlers: MediaPortHandlers): () => void {
    this.handlers.add(handlers);
    return () => this.handlers.delete(handlers);
  }
  emit(key: keyof MediaPortHandlers): void {
    for (const h of this.handlers) h[key]?.();
  }
}

function makeTransport(failLoad = false) {
  const port = new FakePort();
  port.failLoad = failLoad;
  const transport = new MediaElementTransport(port);
  const snaps: TransportSnapshot[] = [];
  transport.subscribe((s) => snaps.push(s));
  return { port, transport, snaps };
}

const SRC: MediaSource = { kind: "blob", blob: new Blob(["x"]) };

describe("load", () => {
  it("empty → loading → ready with snapshots on each step", async () => {
    const { transport, snaps } = makeTransport();
    await transport.load(SRC);
    expect(transport.getSnapshot().status).toBe("ready");
    expect(snaps.map((s) => s.status)).toEqual(["loading", "ready"]);
  });

  it("a failed load flips to error and rejects", async () => {
    const { transport, snaps } = makeTransport(true);
    await expect(transport.load(SRC)).rejects.toThrow();
    expect(transport.getSnapshot().status).toBe("error");
    expect(snaps.map((s) => s.status)).toEqual(["loading", "error"]);
  });
});

describe("play / pause / stop / ended", () => {
  it("play → playing; pause → paused; play after ended rewinds first", async () => {
    const { port, transport } = makeTransport();
    await transport.load(SRC);
    await transport.play();
    expect(transport.getSnapshot().status).toBe("playing");

    transport.pause();
    expect(transport.getSnapshot().status).toBe("paused");

    // `ended` only fires while playing (a paused element never ends).
    await transport.play();
    port.time = 42;
    port.emit("onEnded");
    expect(transport.getSnapshot().status).toBe("ended");

    await transport.play();
    expect(port.seekCalls.at(-1)).toBe(0); // rewind before replay
    expect(transport.getSnapshot().status).toBe("playing");
  });

  it("stop pauses and seeks to 0 (loop start when armed)", async () => {
    const { port, transport } = makeTransport();
    await transport.load(SRC);
    await transport.play();
    transport.setLoop({ start: 10, end: 20 });
    port.time = 15;
    transport.stop();
    expect(port.playing).toBe(false);
    expect(port.time).toBe(10);
    expect(transport.getSnapshot().status).toBe("ready");
  });

  it("no-ops while empty/loading (no source yet)", async () => {
    const { transport } = makeTransport();
    await transport.play(); // status empty — silently ignored
    transport.pause();
    transport.stop();
    expect(transport.getSnapshot().status).toBe("empty");
  });
});

describe("seek / rate / loop", () => {
  it("seek clamps into [0, duration] and unsticks 'ended'", async () => {
    const { port, transport } = makeTransport();
    await transport.load(SRC);
    await transport.play();
    port.emit("onEnded");
    await transport.seek(50);
    expect(port.time).toBe(50);
    expect(transport.getSnapshot().status).toBe("paused");
    await transport.seek(999);
    expect(port.time).toBe(120);
    await transport.seek(-3);
    expect(port.time).toBe(0);
  });

  it("setRate clamps to [0.25, 4] and emits", async () => {
    const { port, transport } = makeTransport();
    transport.setRate(2);
    expect(port.rate).toBe(2);
    transport.setRate(0.01);
    expect(port.rate).toBe(0.25);
    transport.setRate(99);
    expect(port.rate).toBe(4);
  });

  it("setLoop validates the range and clears on null", async () => {
    const { transport } = makeTransport();
    await transport.load(SRC);
    transport.setLoop({ start: 5, end: 5 + MIN_LOOP_SECONDS / 2 });
    expect(transport.getSnapshot().loop).toBeNull(); // too short → rejected
    transport.setLoop({ start: 5, end: 30 });
    expect(transport.getSnapshot().loop).toEqual({ start: 5, end: 30 });
    transport.setLoop(null);
    expect(transport.getSnapshot().loop).toBeNull();
  });

  it("playback past loop.end wraps to loop.start (A-B via media seek)", async () => {
    const { port, transport } = makeTransport();
    await transport.load(SRC);
    await transport.play();
    transport.setLoop({ start: 10, end: 20 });
    port.time = 20.5;
    port.emit("onTimeUpdate");
    expect(port.seekCalls.at(-1)).toBe(10);
  });

  it("load clears a previously armed loop", async () => {
    const { transport } = makeTransport();
    await transport.load(SRC);
    transport.setLoop({ start: 1, end: 2 });
    await transport.load(SRC);
    expect(transport.getSnapshot().loop).toBeNull();
  });

  it("playRange seeks to the range start, plays once, then pauses (#113)",
     async () => {
    const { port, transport } = makeTransport();
    await transport.load(SRC);
    await transport.playRange(10, 20);
    expect(port.seekCalls.at(-1)).toBe(10);
    expect(transport.getSnapshot().status).toBe("playing");
    port.time = 20.5;
    port.emit("onTimeUpdate");
    expect(port.playing).toBe(false);
    expect(transport.getSnapshot().status).toBe("paused");
  });

  it("playRange clears an armed loop and is cleared by seek/stop/setLoop",
     async () => {
    const { port, transport } = makeTransport();
    await transport.load(SRC);
    transport.setLoop({ start: 1, end: 2 });
    await transport.playRange(10, 20);
    expect(transport.getSnapshot().loop).toBeNull();
    // seek cancels the pending one-shot range
    await transport.seek(0);
    await transport.play();
    port.time = 25;
    port.emit("onTimeUpdate");
    expect(port.playing).toBe(true); // no pause at the old range end
    // setLoop also clears it
    await transport.playRange(30, 40);
    transport.setLoop({ start: 1, end: 2 });
    port.time = 41;
    port.emit("onTimeUpdate");
    expect(port.seekCalls.at(-1)).toBe(1); // loop wrap, not one-shot
  });
});

describe("snapshots / listeners", () => {
  it("revision bumps per emit; time mirrors the audio clock", async () => {
    const { port, transport, snaps } = makeTransport();
    await transport.load(SRC);
    port.time = 33;
    port.emit("onTimeUpdate");
    const last = snaps.at(-1)!;
    expect(last.time).toBe(33);
    expect(last.revision).toBe(snaps.length);
    expect(last.duration).toBe(120);
  });

  it("unsubscribe stops notifications; dispose pauses the port", async () => {
    const { port, transport } = makeTransport();
    await transport.load(SRC);
    const spy = vi.fn();
    const off = transport.subscribe(spy);
    transport.pause();
    transport.setRate(1.5);
    expect(spy).toHaveBeenCalled();
    off();
    const calls = spy.mock.calls.length;
    transport.setRate(1.25);
    expect(spy.mock.calls.length).toBe(calls);

    await transport.play();
    transport.dispose();
    expect(port.playing).toBe(false);
  });
});

/**
 * Minimal TransportController adapter for the AUDIO_READY state (UI-020),
 * consistent with the UI-004 spike contract
 * (apps/spikes/waveform/src/transport/types.ts).
 *
 * HornScribe owns this contract: the HTMLMediaElement is an adapter behind
 * `MediaPort`, the audio clock (`getCurrentTime`) is authoritative, and
 * snapshots are emitted to subscribers on state changes and media
 * timeupdate ticks (media-element cadence ≈4 Hz — no rAF, no 60 Hz
 * React churn; the full UI-004 pipeline with its rAF pump/Regions lands
 * with the real waveform view).
 *
 * A-B loop semantics mirror the spike: `[start, end)` wraps via a media
 * seek, which costs a small audible gap — the documented MediaElement
 * constraint, accepted here for the import-stage adapter.
 */
import type { MediaSource } from "./types";

export type TransportStatus =
  | "empty"
  | "loading"
  | "ready"
  | "playing"
  | "paused"
  | "ended"
  | "error";

/** Half-open time range in seconds: [start, end). */
export interface TimeRange {
  start: number;
  end: number;
}

export interface TransportSnapshot {
  status: TransportStatus;
  /** Audio-clock time in seconds (low-frequency mirror; use getCurrentTime
      for per-frame reads). */
  time: number;
  duration: number;
  rate: number;
  loop: TimeRange | null;
  /** 元音源のミュート(#72)。楽譜の演奏だけを聴く用途で使う。 */
  muted: boolean;
  /** Monotonic counter bumped on every emitted snapshot. */
  revision: number;
}

export type TransportListener = (snapshot: TransportSnapshot) => void;
export type Unsubscribe = () => void;

export const MIN_RATE = 0.25;
export const MAX_RATE = 4;
export const SUPPORTED_RATES = [0.5, 0.75, 1, 1.25, 1.5] as const;
/** Loops shorter than this are rejected (noise-level accidental drags). */
export const MIN_LOOP_SECONDS = 0.01;

/** Event feed the port must surface to the adapter. */
export interface MediaPortHandlers {
  onTimeUpdate?(): void;
  onEnded?(): void;
  onError?(): void;
}

/**
 * The media backend seam (UI-004 spike naming). `load` resolves when the
 * source is decoded enough to report a duration and accept play().
 */
export interface MediaPort {
  load(source: MediaSource): Promise<void>;
  play(): Promise<void>;
  pause(): void;
  seekTo(seconds: number): void;
  setRate(rate: number): void;
  setPreservePitch(on: boolean): void;
  setMuted(on: boolean): void;
  getTime(): number;
  getDuration(): number;
  subscribe(handlers: MediaPortHandlers): Unsubscribe;
}

/* ---------------------- HTMLAudioElement backend ---------------------- */

class AudioElementMediaPort implements MediaPort {
  private readonly el: HTMLAudioElement;
  private objectUrl: string | null = null;
  private readonly handlers = new Set<MediaPortHandlers>();

  constructor(el?: HTMLAudioElement) {
    this.el = el ?? new Audio();
    this.el.preload = "auto";
    this.el.addEventListener("timeupdate", () => this.emit("onTimeUpdate"));
    this.el.addEventListener("ended", () => this.emit("onEnded"));
    this.el.addEventListener("error", () => this.emit("onError"));
  }

  private emit(key: keyof MediaPortHandlers) {
    for (const h of this.handlers) h[key]?.();
  }

  load(source: MediaSource): Promise<void> {
    this.revoke();
    const url =
      source.kind === "url"
        ? source.url
        : ((this.objectUrl = URL.createObjectURL(source.blob)), this.objectUrl);
    return new Promise<void>((resolve, reject) => {
      const cleanup = () => {
        this.el.removeEventListener("loadedmetadata", ok);
        this.el.removeEventListener("error", ng);
      };
      const ok = () => {
        cleanup();
        resolve();
      };
      const ng = () => {
        cleanup();
        reject(new Error("media element could not load the source"));
      };
      this.el.addEventListener("loadedmetadata", ok, { once: true });
      this.el.addEventListener("error", ng, { once: true });
      this.el.src = url;
    });
  }

  private revoke() {
    if (this.objectUrl) {
      URL.revokeObjectURL(this.objectUrl);
      this.objectUrl = null;
    }
  }

  play(): Promise<void> {
    return this.el.play();
  }
  pause(): void {
    this.el.pause();
  }
  seekTo(seconds: number): void {
    this.el.currentTime = seconds;
  }
  setRate(rate: number): void {
    this.el.playbackRate = rate;
  }
  setPreservePitch(on: boolean): void {
    // Set the standard property plus the historical vendor-prefixed ones —
    // engines ignore the names they do not implement.
    const el = this.el as HTMLAudioElement & {
      mozPreservesPitch?: boolean;
      webkitPreservesPitch?: boolean;
    };
    el.preservesPitch = on;
    el.mozPreservesPitch = on;
    el.webkitPreservesPitch = on;
  }
  setMuted(on: boolean): void {
    this.el.muted = on;
  }
  getTime(): number {
    return this.el.currentTime;
  }
  getDuration(): number {
    return Number.isFinite(this.el.duration) ? this.el.duration : 0;
  }
  subscribe(handlers: MediaPortHandlers): Unsubscribe {
    this.handlers.add(handlers);
    return () => this.handlers.delete(handlers);
  }
}

/* ------------------------------ controller ------------------------------ */

export class MediaElementTransport {
  private readonly port: MediaPort;
  private status: TransportStatus = "empty";
  private rate = 1;
  private loop: TimeRange | null = null;
  /** #113: one-shot range playback - pause when the clock reaches this.
   *  Cleared by stop/seek/setLoop/load; survives pause+resume. */
  private playUntil: number | null = null;
  private muted = false;
  private revision = 0;
  private readonly listeners = new Set<TransportListener>();

  constructor(port?: MediaPort) {
    this.port = port ?? new AudioElementMediaPort();
    this.port.subscribe({
      onTimeUpdate: () => {
        if (this.status === "playing") {
          const t = this.port.getTime();
          if (this.loop && t >= this.loop.end) {
            // A-B wrap via media seek - see doc header for the known
            // ~60 ms MediaElement gap measured in the UI-004 spike.
            this.port.seekTo(this.loop.start);
          } else if (this.playUntil != null && t >= this.playUntil) {
            // #113: one-shot range playback - pause at the range end.
            this.playUntil = null;
            this.port.pause();
            this.status = "paused";
          }
        }
        this.emit();
      },
      onEnded: () => {
        if (this.status === "playing") {
          this.status = "ended";
          this.emit();
        }
      },
      onError: () => {
        if (this.status !== "empty") {
          this.status = "error";
          this.emit();
        }
      },
    });
  }

  /** Load a source. Resolves when ready to play; rejects → status "error". */
  async load(source: MediaSource): Promise<void> {
    this.status = "loading";
    this.loop = null;
    this.playUntil = null;
    this.emit();
    try {
      await this.port.load(source);
      this.status = "ready";
    } catch (e) {
      this.status = "error";
      this.emit();
      throw e;
    }
    this.emit();
  }

  async play(): Promise<void> {
    if (this.status === "empty" || this.status === "loading") return;
    if (this.status === "ended") this.port.seekTo(0);
    if (this.status === "playing") return;
    await this.port.play();
    this.status = "playing";
    this.emit();
  }

  pause(): void {
    if (this.status !== "playing") return;
    this.port.pause();
    this.status = "paused";
    this.emit();
  }

  /** Pause and return to t=0 (or the loop start when a loop is armed). */
  stop(): void {
    if (this.status === "empty" || this.status === "loading") return;
    this.port.pause();
    this.port.seekTo(this.loop?.start ?? 0);
    this.playUntil = null;
    this.status = "ready";
    this.emit();
  }

  /** Seek to an absolute position in seconds, clamped to [0, duration]. */
  async seek(seconds: number): Promise<void> {
    const duration = this.port.getDuration();
    const target = Math.min(Math.max(seconds, 0), duration);
    this.port.seekTo(target);
    this.playUntil = null;
    if (this.status === "ended") this.status = "paused";
    this.emit();
  }

  /** #113 spec 8 "選択範囲を再生": play [start, end) once, then pause at
   *  the range end. Clears any armed A-B loop so the one-shot range is
   *  authoritative; a later toggleLoop re-arms looping normally. */
  async playRange(start: number, end: number): Promise<void> {
    if (this.status === "empty" || this.status === "loading") return;
    const duration = this.port.getDuration();
    const s = Math.min(Math.max(start, 0), duration);
    const e = Math.min(Math.max(end, 0), duration);
    if (e - s < MIN_LOOP_SECONDS) return;
    this.loop = null;
    this.playUntil = e;
    this.port.seekTo(s);
    if (this.status !== "playing") {
      await this.port.play();
      this.status = "playing";
    }
    this.emit();
  }

  /** Playback rate, clamped to [MIN_RATE, MAX_RATE]. */
  setRate(rate: number): void {
    this.rate = Math.min(MAX_RATE, Math.max(MIN_RATE, rate));
    this.port.setRate(this.rate);
    this.emit();
  }

  /** Request pitch preservation for rate != 1 (backend permitting). */
  setPreservePitch(on: boolean): void {
    this.port.setPreservePitch(on);
    this.emit();
  }

  /** 元音源のミュート(#72)。ミュートはメディア要素側の属性なので、
      ループバック録音中でも録音対象の音は止まらない — モニターの
      聴こえ方だけを切る。 */
  setMuted(on: boolean): void {
    if (this.muted === on) return;
    this.muted = on;
    this.port.setMuted(on);
    this.emit();
  }

  /** Arm (TimeRange) or clear (null) the A-B loop. Degenerate/inverted
      ranges and ranges past the media end are rejected (clamped). */
  setLoop(range: TimeRange | null): void {
    this.playUntil = null;
    if (range === null) {
      this.loop = null;
      this.emit();
      return;
    }
    const duration = this.port.getDuration();
    const start = Math.max(0, range.start);
    const end = Math.min(duration, range.end);
    if (end - start < MIN_LOOP_SECONDS) return;
    this.loop = { start, end };
    this.emit();
  }

  /** Authoritative audio-clock time — read on demand. */
  getCurrentTime(): number {
    return this.port.getTime();
  }
  getDuration(): number {
    return this.port.getDuration();
  }

  getSnapshot(): TransportSnapshot {
    return {
      status: this.status,
      time: this.port.getTime(),
      duration: this.port.getDuration(),
      rate: this.rate,
      loop: this.loop ? { ...this.loop } : null,
      muted: this.muted,
      revision: this.revision,
    };
  }

  subscribe(listener: TransportListener): Unsubscribe {
    this.listeners.add(listener);
    return () => this.listeners.delete(listener);
  }

  dispose(): void {
    this.listeners.clear();
    this.port.pause();
  }

  private emit(): void {
    this.revision += 1;
    const snap = this.getSnapshot();
    for (const l of this.listeners) l(snap);
  }
}

import { describe, expect, it } from "vitest";
import {
  clientXInView,
  clientXToSeconds,
  clampView,
  fullView,
  isFullView,
  normalizeSelection,
  panView,
  selectionBand,
  selectionBandInView,
  zoomView,
} from "./selection";

describe("clientXToSeconds", () => {
  it("maps the strip's left/right edges to 0/duration", () => {
    expect(clientXToSeconds(0, 0, 1000, 60)).toBe(0);
    expect(clientXToSeconds(1000, 0, 1000, 60)).toBe(60);
    expect(clientXToSeconds(500, 0, 1000, 60)).toBe(30);
  });

  it("clamps outside the strip", () => {
    expect(clientXToSeconds(-50, 0, 1000, 60)).toBe(0);
    expect(clientXToSeconds(2000, 0, 1000, 60)).toBe(60);
  });

  it("respects a non-zero rect origin", () => {
    expect(clientXToSeconds(300, 100, 400, 40)).toBe(20);
  });

  it("returns 0 for degenerate geometry", () => {
    expect(clientXToSeconds(10, 0, 0, 60)).toBe(0);
    expect(clientXToSeconds(10, 0, 100, 0)).toBe(0);
  });
});

describe("normalizeSelection", () => {
  it("orders a backwards drag", () => {
    expect(normalizeSelection(30, 10, 60)).toEqual({
      startSec: 10,
      endSec: 30,
    });
  });

  it("clamps to the clip", () => {
    expect(normalizeSelection(-5, 100, 60)).toEqual({
      startSec: 0,
      endSec: 60,
    });
  });

  it("keeps a zero-length range (collapsed band)", () => {
    expect(normalizeSelection(20, 20, 60)).toEqual({
      startSec: 20,
      endSec: 20,
    });
  });
});

describe("selectionBand", () => {
  it("returns fractional edges", () => {
    expect(selectionBand({ startSec: 15, endSec: 45 }, 60)).toEqual({
      left: 0.25,
      width: 0.5,
    });
  });

  it("returns null for empty or missing ranges", () => {
    expect(selectionBand(null, 60)).toBeNull();
    expect(selectionBand({ startSec: 30, endSec: 30 }, 60)).toBeNull();
    const inverted = selectionBand({ startSec: 40, endSec: 30 }, 60);
    expect(inverted?.left).toBeCloseTo(0.5);
    expect(inverted?.width).toBeCloseTo(1 / 6);
    expect(selectionBand({ startSec: 0, endSec: 10 }, 0)).toBeNull();
  });
});

describe("view window (#113, spec 8/15 zoom)", () => {
  it("fullView spans the clip and isFullView detects it", () => {
    const v = fullView(60);
    expect(v).toEqual({ startSec: 0, endSec: 60 });
    expect(isFullView(v, 60)).toBe(true);
    expect(isFullView({ startSec: 10, endSec: 60 }, 60)).toBe(false);
  });

  it("zoomView shrinks around the anchor and clamps to the clip", () => {
    const full = fullView(60);
    const z = zoomView(full, 30, 0.5, 60);
    expect(z.endSec - z.startSec).toBeCloseTo(30);
    // anchor stays at the same fractional position (0.5)
    expect((30 - z.startSec) / (z.endSec - z.startSec)).toBeCloseTo(0.5);
    // zooming out past the clip clamps back to full
    expect(isFullView(zoomView(z, 30, 4, 60), 60)).toBe(true);
  });

  it("panView shifts the window without changing its span", () => {
    const v = panView({ startSec: 10, endSec: 20 }, 5, 60);
    expect(v).toEqual({ startSec: 15, endSec: 25 });
    // clamped at both edges
    expect(panView(v, -100, 60)).toEqual({ startSec: 0, endSec: 10 });
    expect(panView(v, 100, 60)).toEqual({ startSec: 50, endSec: 60 });
  });

  it("clientXInView maps inside the zoomed window", () => {
    const view = { startSec: 20, endSec: 40 };
    expect(clientXInView(0, 0, 1000, view)).toBe(20);
    expect(clientXInView(1000, 0, 1000, view)).toBe(40);
    expect(clientXInView(500, 0, 1000, view)).toBe(30);
    expect(clientXInView(-50, 0, 1000, view)).toBe(20);
  });

  it("selectionBandInView clips to the window and drops misses", () => {
    const view = { startSec: 20, endSec: 40 };
    expect(
      selectionBandInView({ startSec: 30, endSec: 50 }, view),
    ).toEqual({ left: 0.5, width: 0.5 });
    expect(
      selectionBandInView({ startSec: 0, endSec: 10 }, view),
    ).toBeNull();
    expect(selectionBandInView(null, view)).toBeNull();
  });

  it("clampView preserves the span at the edges", () => {
    expect(clampView({ startSec: -5, endSec: 15 }, 60)).toEqual({
      startSec: 0,
      endSec: 20,
    });
    expect(clampView({ startSec: 55, endSec: 75 }, 60)).toEqual({
      startSec: 40,
      endSec: 60,
    });
  });
});

/**
 * Waveform range selection math (#88 partial transcription).
 *
 * The waveform strip maps its full width to [0, durationSeconds]. A
 * pointer drag shorter than DRAG_THRESHOLD_PX stays a click (seek); a
 * longer drag becomes a selection range. All functions are pure so the
 * mapping is unit-testable without a DOM.
 */

/** Pointer travel (px) below which a press+release stays a click. */
export const DRAG_THRESHOLD_PX = 6;

/** A committed selection, in audio-clock seconds. */
export interface SelectionRange {
  startSec: number;
  endSec: number;
}

/** Horizontal pointer position -> audio time, clamped to the clip. */
export function clientXToSeconds(
  clientX: number,
  rectLeft: number,
  rectWidth: number,
  durationSec: number,
): number {
  if (rectWidth <= 0 || durationSec <= 0) return 0;
  const ratio = (clientX - rectLeft) / rectWidth;
  return Math.min(1, Math.max(0, ratio)) * durationSec;
}

/** Order + clamp a drag pair into a valid selection. */
export function normalizeSelection(
  aSec: number,
  bSec: number,
  durationSec: number,
): SelectionRange {
  const lo = Math.min(aSec, bSec);
  const hi = Math.max(aSec, bSec);
  const clamp = (v: number) => Math.min(Math.max(v, 0), Math.max(0, durationSec));
  return { startSec: clamp(lo), endSec: clamp(hi) };
}

/**
 * Fractional [0,1] band edges for rendering, or null when the range is
 * empty/inverted (nothing to paint). Live drags use the same path.
 */
export function selectionBand(
  range: SelectionRange | null,
  durationSec: number,
): { left: number; width: number } | null {
  if (!range || durationSec <= 0) return null;
  const norm = normalizeSelection(range.startSec, range.endSec, durationSec);
  if (norm.endSec <= norm.startSec) return null;
  const left = norm.startSec / durationSec;
  const right = norm.endSec / durationSec;
  return { left, width: Math.max(0, right - left) };
}

/* ------------------------------ zoom view ------------------------------- */

/** GUI_UX_SPEC 8/15: the waveform's visible time window ([0, duration]). */
export interface ViewRange {
  startSec: number;
  endSec: number;
}

/** Whole-clip view - the default before any Ctrl+wheel zoom. */
export function fullView(durationSec: number): ViewRange {
  return { startSec: 0, endSec: Math.max(0, durationSec) };
}

/** Smallest zoomable window - keeps a reset reachable and stops
 *  degenerate zero-width views. */
export const MIN_VIEW_SECONDS = 0.5;

/** True when the view shows the whole clip (zoom reset state). */
export function isFullView(view: ViewRange, durationSec: number): boolean {
  return (
    view.startSec <= 0 && view.endSec >= Math.max(0, durationSec) - 1e-9
  );
}

/** Clamp a candidate window into [0, duration], preserving its span. */
export function clampView(view: ViewRange, durationSec: number): ViewRange {
  const dur = Math.max(0, durationSec);
  const span = Math.min(Math.max(view.endSec - view.startSec, 0), dur);
  if (span <= 0 || dur <= 0) return fullView(dur);
  let start = view.startSec;
  if (start < 0) start = 0;
  if (start + span > dur) start = dur - span;
  return { startSec: start, endSec: start + span };
}

/**
 * Ctrl+wheel zoom (spec 15): scale the window around `anchorSec` (the
 * cursor's audio time) by `factor` (<1 zooms in, >1 zooms out), clamped
 * to [MIN_VIEW_SECONDS, duration].
 */
export function zoomView(
  view: ViewRange,
  anchorSec: number,
  factor: number,
  durationSec: number,
): ViewRange {
  const dur = Math.max(0, durationSec);
  if (dur <= 0) return fullView(dur);
  const clamped = clampView(view, dur);
  const span = clamped.endSec - clamped.startSec;
  const next = Math.min(dur, Math.max(MIN_VIEW_SECONDS, span * factor));
  const anchor = Math.min(Math.max(anchorSec, 0), dur);
  const t = span > 0 ? (anchor - clamped.startSec) / span : 0.5;
  return clampView(
    { startSec: anchor - t * next, endSec: anchor - t * next + next },
    dur,
  );
}

/** Wheel horizontal navigation (spec 8): shift the window by `deltaSec`. */
export function panView(
  view: ViewRange,
  deltaSec: number,
  durationSec: number,
): ViewRange {
  return clampView(
    { startSec: view.startSec + deltaSec, endSec: view.endSec + deltaSec },
    durationSec,
  );
}

/** Pointer position -> audio time inside a zoomed window. */
export function clientXInView(
  clientX: number,
  rectLeft: number,
  rectWidth: number,
  view: ViewRange,
): number {
  if (rectWidth <= 0) return view.startSec;
  const ratio = Math.min(1, Math.max(0, (clientX - rectLeft) / rectWidth));
  return view.startSec + ratio * Math.max(0, view.endSec - view.startSec);
}

/**
 * Fractional [0,1] band edges inside the current view (clamped to the
 * window), or null when the range does not intersect it.
 */
export function selectionBandInView(
  range: SelectionRange | null,
  view: ViewRange,
): { left: number; width: number } | null {
  if (!range) return null;
  const lo = Math.min(range.startSec, range.endSec);
  const hi = Math.max(range.startSec, range.endSec);
  const span = view.endSec - view.startSec;
  if (span <= 0) return null;
  const left = Math.max(lo, view.startSec);
  const right = Math.min(hi, view.endSec);
  if (right <= left) return null;
  return { left: (left - view.startSec) / span, width: (right - left) / span };
}

/**
 * @vitest-environment jsdom
 *
 * Keyboard dispatcher tests (issue UI-012): IME safety, text-entry and
 * control scoping, disabled-command swallowing, auto-repeat and multi-chord
 * sequences.
 */

import { describe, expect, it, vi } from "vitest";
import { CommandRegistry } from "../commands/registry";
import { createCommandDefinitions } from "../commands/definitions";
import type {
  Command,
  CommandContext,
  CommandSnapshot,
} from "../commands/types";
import { KeyboardDispatcher } from "./dispatcher";
import type { KeyEventLike } from "./keys";

const EMPTY: CommandSnapshot = {
  hasAudio: false,
  hasScore: false,
  isTranscribing: false,
  isPlaying: false,
  loopEnabled: false,
  pitch: "concert",
  canUndo: false,
  canRedo: false,
  hasSelection: false,
  hasWaveformSelection: false,
  reviewOpen: false,
  reviewCount: 0,
      isRecording: false,
      isRecordingPaused: false,
      auditionEnabled: false,
  view: "workspace",
};

const WITH_AUDIO: CommandSnapshot = { ...EMPTY, hasAudio: true };

function mockContext() {
  const calls: string[] = [];
  const spy = (name: string) => vi.fn(() => calls.push(name));
  const ctx: CommandContext = {
    openAudio: spy("openAudio"),
    transcribe: spy("transcribe"),
    togglePlayPause: spy("togglePlayPause"),
    stop: spy("stop"),
    jumpBack: spy("jumpBack"),
    jumpForward: spy("jumpForward"),
    seekToStart: spy("seekToStart"),
    seekToEnd: spy("seekToEnd"),
    toggleLoop: spy("toggleLoop"),
    setPitchView: spy("setPitchView"),
    openReview: spy("openReview"),
    reviewNext: spy("reviewNext"),
    reviewPrevious: spy("reviewPrevious"),
    undo: spy("undo"),
    redo: spy("redo"),
    openExport: spy("openExport"),
    zoomScoreIn: spy("zoomScoreIn"),
    zoomScoreOut: spy("zoomScoreOut"),
    zoomScoreFit: spy("zoomScoreFit"),
    clearSelection: spy("clearSelection"),
    openSettings: spy("openSettings"),
    openDiagnostics: spy("openDiagnostics"),
    focusNextRegion: spy("focusNextRegion"),
    focusPreviousRegion: spy("focusPreviousRegion"),
    announce: spy("announce"),
  };
  return { ctx, calls };
}

function key(
  k: string,
  init: Partial<KeyEventLike> = {},
): KeyEventLike {
  return {
    key: k,
    ctrlKey: false,
    shiftKey: false,
    altKey: false,
    ...init,
  };
}

function setup(
  snapshot: CommandSnapshot,
  commands: readonly Command[] = createCommandDefinitions(),
) {
  const { ctx, calls } = mockContext();
  const dispatcher = new KeyboardDispatcher({
    registry: new CommandRegistry(commands),
    getSnapshot: () => snapshot,
    context: ctx,
  });
  return { dispatcher, calls };
}

describe("basic dispatch", () => {
  it("runs a bound command and asks for preventDefault", () => {
    const { dispatcher, calls } = setup(WITH_AUDIO);
    const result = dispatcher.handleKeyDown(key(" "));
    expect(result).toMatchObject({
      kind: "ran",
      commandId: "transport.playPause",
      shouldPreventDefault: true,
    });
    expect(calls).toEqual(["togglePlayPause"]);
  });

  it("K is the second play/pause binding (§9)", () => {
    const { dispatcher, calls } = setup(WITH_AUDIO);
    expect(dispatcher.handleKeyDown(key("k")).commandId).toBe(
      "transport.playPause",
    );
    expect(calls).toEqual(["togglePlayPause"]);
  });

  it("letters match case-insensitively but modifiers stay strict", () => {
    const { dispatcher, calls } = setup(WITH_AUDIO);
    // CapsLock makes e.key "J" — still the same chord.
    expect(dispatcher.handleKeyDown(key("J")).commandId).toBe(
      "transport.jumpBack",
    );
    // But Shift+L is not bound — modifier mismatch means no dispatch.
    const shifted = dispatcher.handleKeyDown(key("L", { shiftKey: true }));
    expect(shifted.kind).toBe("unmatched");
    expect(calls).toEqual(["jumpBack"]);
  });

  it("unmatched keys pass through without preventDefault", () => {
    const { dispatcher } = setup(WITH_AUDIO);
    const result = dispatcher.handleKeyDown(key("q"));
    expect(result).toMatchObject({
      kind: "unmatched",
      shouldPreventDefault: false,
    });
  });
});

describe("disabled commands stay non-executable", () => {
  it("swallows a known-but-disabled shortcut (no run, preventDefault)", () => {
    const { dispatcher, calls } = setup(EMPTY); // no audio
    const result = dispatcher.handleKeyDown(key(" "));
    expect(result).toMatchObject({
      kind: "disabled",
      commandId: "transport.playPause",
      shouldPreventDefault: true,
    });
    expect(calls).toEqual([]);
  });

  it("Ctrl+Z does nothing when the undo stack is empty", () => {
    const { dispatcher, calls } = setup(EMPTY);
    expect(dispatcher.handleKeyDown(key("z", { ctrlKey: true })).kind).toBe(
      "disabled",
    );
    expect(calls).toEqual([]);
  });
});

describe("IME safety (UI_COPY_CONTRACT / MASTER_PLAN §8)", () => {
  it("ignores events during composition", () => {
    const { dispatcher, calls } = setup(WITH_AUDIO);
    const result = dispatcher.handleKeyDown(
      key("k", { isComposing: true }),
    );
    expect(result.kind).toBe("suppressed");
    expect(result.shouldPreventDefault).toBe(false);
    expect(calls).toEqual([]);
  });

  it("ignores the keyCode 229 IME sentinel", () => {
    const { dispatcher, calls } = setup(WITH_AUDIO);
    const result = dispatcher.handleKeyDown(
      key("Process", { keyCode: 229 }),
    );
    expect(result.kind).toBe("suppressed");
    expect(calls).toEqual([]);
  });
});

describe("focus scopes", () => {
  function el(html: string): HTMLElement {
    const host = document.createElement("div");
    host.innerHTML = html;
    const node = host.firstElementChild as HTMLElement;
    document.body.appendChild(node);
    return node;
  }

  it("suppresses J/K/L inside text input (spec §9)", () => {
    const { dispatcher, calls } = setup(WITH_AUDIO);
    const input = el('<input type="text">');
    const result = dispatcher.handleKeyDown(key("k", { target: input }));
    expect(result.kind).toBe("suppressed");
    expect(calls).toEqual([]);
    input.remove();
  });

  it("suppresses Ctrl+Z inside text input — field-level undo wins", () => {
    const { dispatcher, calls } = setup({ ...EMPTY, canUndo: true });
    const textarea = el("<textarea></textarea>");
    const result = dispatcher.handleKeyDown(
      key("z", { ctrlKey: true, target: textarea }),
    );
    expect(result.kind).toBe("suppressed");
    expect(calls).toEqual([]);
    textarea.remove();
  });

  it("suppresses everything inside a modal surface by default", () => {
    const { dispatcher, calls } = setup(WITH_AUDIO);
    const dialog = el('<div role="dialog"><button type="button">x</button></div>');
    const inside = dialog.querySelector("button")!;
    for (const k of ["k", " "]) {
      expect(
        dispatcher.handleKeyDown(key(k, { target: inside })).kind,
      ).toBe("suppressed");
    }
    // Even a Ctrl binding does not fire inside a modal.
    expect(
      dispatcher.handleKeyDown(
        key("o", { ctrlKey: true, target: inside }),
      ).kind,
    ).toBe("suppressed");
    expect(calls).toEqual([]);
    dialog.remove();
  });

  it("Space on a focused button belongs to the button, not transport", () => {
    const { dispatcher, calls } = setup(WITH_AUDIO);
    const button = el('<button type="button">開く</button>');
    const result = dispatcher.handleKeyDown(key(" ", { target: button }));
    expect(result.kind).toBe("suppressed");
    expect(calls).toEqual([]);
    button.remove();
  });

  it("J on a focused button still dispatches — buttons don't consume J", () => {
    const { dispatcher, calls } = setup(WITH_AUDIO);
    const button = el('<button type="button">開く</button>');
    const result = dispatcher.handleKeyDown(key("j", { target: button }));
    expect(result).toMatchObject({
      kind: "ran",
      commandId: "transport.jumpBack",
    });
    expect(calls).toEqual(["jumpBack"]);
    button.remove();
  });

  it("Space on a radio stays with the control (roving tabindex)", () => {
    const { dispatcher } = setup(WITH_AUDIO);
    const radio = el('<div role="radio" tabindex="0"></div>');
    // Space checks the radio instead of toggling playback.
    expect(
      dispatcher.handleKeyDown(key(" ", { target: radio })).kind,
    ).toBe("suppressed");
    radio.remove();
  });

  it("Ctrl bindings still work from inside a focused control", () => {
    const { dispatcher, calls } = setup(EMPTY);
